update mall_order
order_no = #{orderNo}, merchant_id = #{merchantId}, user_id = #{userId}, store_id = #{storeId}, total_amount = #{totalAmount}, pay_amount = #{payAmount}, commission = #{commission}, merchant_income = #{merchantIncome}, coupon_id = #{couponId}, coupon_amount = #{couponAmount}, groupon_id = #{grouponId}, status = #{status}, write_off_code = #{writeOffCode}, write_off_status = #{writeOffStatus}, write_off_time = #{writeOffTime}, write_off_user_id = #{writeOffUserId}, valid_days = #{validDays}, pay_time = #{payTime}, use_time = #{useTime}, complete_time = #{completeTime}, cancel_time = #{cancelTime}, refund_time = #{refundTime},
